// =====================================================
//                     РЕЖИМ СВЕТА
// =====================================================

enum LightMode {
  MODE_AUTO = 0,
  MODE_ON   = 1,
  MODE_OFF  = 2
};

LightMode lightMode = MODE_AUTO;

bool lightState = false;
bool printerBusy = false;

String printerState = "UNKNOWN";

// =====================================================
//                  УПРАВЛЕНИЕ СВЕТОМ
// =====================================================

void setLight(bool on) {

  if (lightState == on) {
    return;
  }

  lightState = on;

  digitalWrite(
    LED_PIN,
    on ? LED_ON : LED_OFF
  );

  if (on) {
    Serial.println(">>> LIGHT ON");
  } else {
    Serial.println(">>> LIGHT OFF");
  }
}

// =====================================================
//                  ПРИМЕНЕНИЕ РЕЖИМА
// =====================================================

void applyLightMode() {

  if (lightMode == MODE_ON) {

    setLight(true);

  } else if (lightMode == MODE_OFF) {

    setLight(false);

  } else {

    // AUTO
    setLight(printerBusy);
  }
}

// =====================================================
//                   НАЗВАНИЕ РЕЖИМА
// =====================================================

String modeName() {

  if (lightMode == MODE_ON) {
    return "ON";
  }

  if (lightMode == MODE_OFF) {
    return "OFF";
  }

  return "AUTO";
}

// =====================================================
//                  СОХРАНЕНИЕ РЕЖИМА
// =====================================================

void saveMode() {

  preferences.putInt(
    "mode",
    (int)lightMode
  );
}

// =====================================================
//              СОСТОЯНИЕ ПРИНТЕРА
// =====================================================

void handlePrinterState(String state) {

  state.trim();
  state.toUpperCase();

  if (state.length() == 0) {
    return;
  }

  // Не спамим одинаковыми состояниями
  if (printerState == state) {
    return;
  }

  printerState = state;

  Serial.print("Printer state: ");
  Serial.println(printerState);

  /*
      AUTO:

      INIT      -> свет ВКЛ
      PREPARE   -> свет ВКЛ
      RUNNING   -> свет ВКЛ
      PAUSE     -> свет ВКЛ
      SLICING   -> свет ВКЛ

      IDLE      -> свет ВЫКЛ
      FINISH    -> свет ВЫКЛ
      FAILED    -> свет ВЫКЛ
      OFFLINE   -> свет ВЫКЛ
  */

  printerBusy =
      state == "INIT" ||
      state == "PREPARE" ||
      state == "RUNNING" ||
      state == "PAUSE" ||
      state == "SLICING";

  applyLightMode();
}

// =====================================================
//             ИЩЕМ gcode_state В JSON
// =====================================================

void parsePrinterMessage(
  byte* payload,
  unsigned int length
) {

  String message;
  message.reserve(length + 1);

  for (unsigned int i = 0; i < length; i++) {
    message += (char)payload[i];
  }

  int keyPos =
      message.indexOf("\"gcode_state\"");

  if (keyPos < 0) {
    return;
  }

  int colon =
      message.indexOf(':', keyPos);

  if (colon < 0) {
    return;
  }

  int quote1 =
      message.indexOf('"', colon + 1);

  if (quote1 < 0) {
    return;
  }

  int quote2 =
      message.indexOf('"', quote1 + 1);

  if (quote2 < 0) {
    return;
  }

  String state =
      message.substring(
        quote1 + 1,
        quote2
      );

  handlePrinterState(state);
}

// =====================================================
//                    MQTT CALLBACK
// =====================================================

void mqttCallback(
  char* topic,
  byte* payload,
  unsigned int length
) {

  lastMqttMessage = millis();

  Serial.print("MQTT RX: ");
  Serial.print(length);
  Serial.println(" bytes");

  parsePrinterMessage(
    payload,
    length
  );
}

// =====================================================
//                 MQTT ПОДКЛЮЧЕНИЕ
// =====================================================

bool connectMQTT() {

  if (WiFi.status() != WL_CONNECTED) {
    return false;
  }

  Serial.println();
  Serial.println(
    "Connecting to Bambu A1 MQTT..."
  );

  bool ok =
      mqtt.connect(
        MQTT_CLIENT_ID,
        "bblp",
        ACCESS_CODE
      );

  if (!ok) {

    Serial.print(
      "MQTT CONNECT ERROR: "
    );

    Serial.println(
      mqtt.state()
    );

    return false;
  }

  Serial.println(
    "MQTT CONNECTED"
  );

  bool subscribed =
      mqtt.subscribe(
        reportTopic.c_str()
      );

  if (subscribed) {

    Serial.print(
      "Subscribed: "
    );

    Serial.println(
      reportTopic
    );

  } else {

    Serial.println(
      "MQTT SUBSCRIBE ERROR"
    );
  }

  lastMqttMessage = millis();

  return true;
}

// =====================================================
//                       WI-FI
// =====================================================

void connectWiFi() {

  Serial.println();
  Serial.print(
    "Connecting Wi-Fi: "
  );

  Serial.println(
    WIFI_SSID
  );

  WiFi.mode(WIFI_STA);

  // Для более стабильной связи ESP32
  WiFi.setSleep(false);

  WiFi.setHostname(
    HOSTNAME
  );

  WiFi.begin(
    WIFI_SSID,
    WIFI_PASSWORD
  );

  unsigned long start =
      millis();

  while (
    WiFi.status() != WL_CONNECTED &&
    millis() - start < 20000
  ) {

    delay(500);
    Serial.print(".");
  }

  Serial.println();

  if (
    WiFi.status() ==
    WL_CONNECTED
  ) {

    Serial.println(
      "Wi-Fi CONNECTED"
    );

    Serial.print(
      "ESP32 IP: "
    );

    Serial.println(
      WiFi.localIP()
    );

    Serial.print(
      "RSSI: "
    );

    Serial.print(
      WiFi.RSSI()
    );

    Serial.println(
      " dBm"
    );

  } else {

    Serial.println(
      "Wi-Fi FAILED"
    );
  }
}

