void setupWebServer() {

  server.on(
    "/",
    HTTP_GET,
    []() {

      server.send(
        200,
        "text/html; charset=utf-8",
        getHtml()
      );
    }
  );

  server.on(
    "/auto",
    HTTP_GET,
    []() {

      lightMode =
          MODE_AUTO;

      saveMode();
      applyLightMode();

      server.send(
        200,
        "text/plain",
        "AUTO"
      );
    }
  );

  server.on(
    "/on",
    HTTP_GET,
    []() {

      lightMode =
          MODE_ON;

      saveMode();
      applyLightMode();

      server.send(
        200,
        "text/plain",
        "ON"
      );
    }
  );

  server.on(
    "/off",
    HTTP_GET,
    []() {

      lightMode =
          MODE_OFF;

      saveMode();
      applyLightMode();

      server.send(
        200,
        "text/plain",
        "OFF"
      );
    }
  );

  server.on(
    "/status",
    HTTP_GET,
    []() {

      String json = "{";

      json +=
        "\"printer\":\"" +
        printerState +
        "\",";

      json +=
        "\"light\":" +
        String(
          lightState ?
          "true" :
          "false"
        ) +
        ",";

      json +=
        "\"mode\":\"" +
        modeName() +
        "\",";

      json +=
        "\"mqtt\":" +
        String(
          mqtt.connected() ?
          "true" :
          "false"
        ) +
        ",";

      json +=
        "\"rssi\":" +
        String(
          WiFi.RSSI()
        );

      json += "}";

      server.send(
        200,
        "application/json",
        json
      );
    }
  );

  server.begin();

  Serial.println(
    "Web server started"
  );
}

// =====================================================
//                        SETUP
// =====================================================

void setup() {

  Serial.begin(
    115200
  );

  delay(
    1000
  );

  Serial.println();
  Serial.println(
    "============================"
  );

  Serial.println(
    " Bambu A1 Smart Light"
  );

  Serial.println(
    " GPIO 25"
  );

  Serial.println(
    "============================"
  );

  // GPIO 25

  pinMode(
    LED_PIN,
    OUTPUT
  );

  digitalWrite(
    LED_PIN,
    LED_OFF
  );

  lightState = false;

  // ===================================================
  // СОХРАНЁННЫЙ РЕЖИМ
  // ===================================================

  preferences.begin(
    "bambulight",
    false
  );

  int savedMode =
      preferences.getInt(
        "mode",
        MODE_AUTO
      );

  if (
    savedMode >= MODE_AUTO &&
    savedMode <= MODE_OFF
  ) {

    lightMode =
        (LightMode)savedMode;

  } else {

    lightMode =
        MODE_AUTO;
  }

  // ===================================================
  // MQTT TOPIC
  // ===================================================

  reportTopic =
      "device/" +
      String(PRINTER_SN) +
      "/report";

  // ===================================================
  // WI-FI
  // ===================================================

  connectWiFi();

  // ===================================================
  // WEB SERVER
  // ===================================================

  setupWebServer();

  // ===================================================
  // mDNS
  // ===================================================

  if (
    WiFi.status() ==
    WL_CONNECTED
  ) {

    if (
      MDNS.begin(
        HOSTNAME
      )
    ) {

      Serial.println(
        "mDNS OK"
      );

      Serial.println(
        "http://bambulight.local"
      );
    }
  }

  // ===================================================
  // TLS
  // ===================================================

  secureClient.setInsecure();

  // ===================================================
  // MQTT
  // ===================================================

  mqtt.setServer(
    PRINTER_IP,
    8883
  );

  mqtt.setCallback(
    mqttCallback
  );

  bool bufferOK =
      mqtt.setBufferSize(
        65535
      );

  if (bufferOK) {

    Serial.println(
      "MQTT buffer: 65535"
    );

  } else {

    Serial.println(
      "MQTT buffer allocation FAILED"
    );
  }

  mqtt.setSocketTimeout(
    30
  );

  mqtt.setKeepAlive(
    30
  );

  // ===================================================
  // ПЕРВОЕ ПОДКЛЮЧЕНИЕ
  // ===================================================

  if (
    WiFi.status() ==
    WL_CONNECTED
  ) {

    connectMQTT();
  }

  applyLightMode();

  // ===================================================
  // АДРЕС ПАНЕЛИ
  // ===================================================

  Serial.println();

  Serial.println(
    "PHONE CONTROL:"
  );

  Serial.println(
    "http://bambulight.local"
  );

  Serial.print(
    "http://"
  );

  Serial.println(
    WiFi.localIP()
  );
}

// =====================================================
//                         LOOP
// =====================================================

void loop() {

  // ===================================================
  // WEB
  // ===================================================

  server.handleClient();

  // ===================================================
  // WI-FI
  // ===================================================

  if (
    WiFi.status() !=
    WL_CONNECTED
  ) {

    if (
      millis() -
      lastWiFiReconnect >=
      WIFI_RECONNECT_INTERVAL
    ) {

      lastWiFiReconnect =
          millis();

      Serial.println(
        "Wi-Fi reconnect..."
      );

      WiFi.disconnect();

      WiFi.begin(
        WIFI_SSID,
        WIFI_PASSWORD
      );
    }

    delay(5);

    return;
  }

  // ===================================================
  // MQTT
  // ===================================================

  if (
    mqtt.connected()
  ) {

    mqtt.loop();

  } else {

    if (
      millis() -
      lastMqttReconnect >=
      MQTT_RECONNECT_INTERVAL
    ) {

      lastMqttReconnect =
          millis();

      Serial.print(
        "MQTT disconnected. State: "
      );

      Serial.println(
        mqtt.state()
      );

      connectMQTT();
    }
  }

  // ===================================================
  // TIMEOUT ПРИНТЕРА
  // ===================================================

  if (
    lastMqttMessage != 0 &&
    millis() -
    lastMqttMessage >
    PRINTER_TIMEOUT
  ) {

    if (
      printerState !=
      "OFFLINE"
    ) {

      Serial.println(
        "Printer MQTT timeout"
      );

      printerState =
          "OFFLINE";

      printerBusy =
          false;

      applyLightMode();
    }
  }

  delay(2);
}
